const cfg = $('Configure ICP & Scoring Rules').first().json;
const hotThreshold = Number(cfg.hotScoreThreshold || 65);
const rawItems = $input.all().map((i) => i.json).filter((r) => r && typeof r === 'object');

const cleanDomain = (val) => {
  if (!val) return '';
  return String(val)
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\//, '')
    .replace(/^www\./, '')
    .split('/')[0]
    .split('?')[0];
};

const scoreByTrigger = {
  funding: 45,
  sec_form_d_funding: 50,
  acquisition: 40,
  exec_hire: 35,
  expansion: 30,
  partnership: 25,
  product_launch: 20,
  high_comp_hiring: 30,
  layoffs: 20,
  regulatory_lawsuit: 20
};

const accounts = new Map();

for (const item of rawItems) {
  let source = '';
  let company = '';
  let domain = '';
  let trigger = '';
  let headline = '';
  let evidenceUrl = '';
  let eventDate = '';
  let contextNote = '';

  if (item.articleId && item.primaryTrigger) {
    source = 'google_news';
    company = item.matchedCompany || '';
    domain = cleanDomain(item.companyDomain || (Array.isArray(item.mentionedDomains) ? item.mentionedDomains[0] : ''));
    trigger = String(item.primaryTrigger).toLowerCase();
    headline = item.title || '';
    evidenceUrl = item.url || item.googleNewsUrl || '';
    eventDate = item.publishedAt || '';
    contextNote = item.icebreakerSnippet || headline;
  } else if (item.accessionNumber && item.companyName) {
    source = 'sec_form_d';
    company = item.companyName;
    domain = cleanDomain(item.companyDomain || '');
    trigger = 'sec_form_d_funding';
    const sold = Number(item.totalAmountSoldUsd || 0).toLocaleString('en-US');
    headline = `SEC Form D filing: ${item.companyName} raised $${sold} (${item.industryGroup || 'Tech'})`;
    evidenceUrl = item.secFilingUrl || '';
    eventDate = item.filingDate || '';
    contextNote = `${headline}. Lead executive: ${item.leadExecutiveName || 'Founder'} (${item.leadExecutiveTitle || 'Executive'}).`;
  } else if (item.jobKey && item.title) {
    source = 'ats_hiring';
    company = item.company || '';
    domain = cleanDomain(item.companyDomain || '');
    trigger = 'high_comp_hiring';
    headline = `Hiring ${item.title} (${item.salarySummary || 'High-comp'})`;
    evidenceUrl = item.jobUrl || '';
    eventDate = item.postedAt || '';
    const tags = Array.isArray(item.hiringTriggerTags) ? item.hiringTriggerTags.join(', ') : '';
    contextNote = `${headline} at ${company}${tags ? ` [signals: ${tags}]` : ''}.`;
  } else {
    continue;
  }

  const accountKey = domain || company.toLowerCase().replace(/[^a-z0-9]+/g, '');
  if (!accountKey) continue;

  if (!accounts.has(accountKey)) {
    accounts.set(accountKey, {
      accountKey,
      company: company || domain,
      domain,
      sources: [],
      triggers: [],
      headlines: [],
      evidenceUrls: [],
      latestDate: eventDate,
      contextNotes: [],
      baseScore: 0
    });
  }

  const acc = accounts.get(accountKey);
  if (!acc.company && company) acc.company = company;
  if (!acc.domain && domain) acc.domain = domain;
  if (!acc.sources.includes(source)) acc.sources.push(source);
  if (!acc.triggers.includes(trigger)) {
    acc.triggers.push(trigger);
    acc.baseScore += (scoreByTrigger[trigger] || 20);
  }
  if (headline && acc.headlines.length < 3 && !acc.headlines.includes(headline)) acc.headlines.push(headline);
  if (evidenceUrl && acc.evidenceUrls.length < 3 && !acc.evidenceUrls.includes(evidenceUrl)) acc.evidenceUrls.push(evidenceUrl);
  if (contextNote && acc.contextNotes.length < 3) acc.contextNotes.push(contextNote);
  if (eventDate && (!acc.latestDate || eventDate > acc.latestDate)) acc.latestDate = eventDate;
}

const scoredAccounts = [...accounts.values()].map((acc) => {
  const convergenceBonus = acc.sources.length >= 2 ? 25 : 0;
  const domainBonus = acc.domain ? 15 : 0;
  const intentScore = Math.min(100, acc.baseScore + convergenceBonus + domainBonus);
  return {
    ...acc,
    intentScore,
    hotScoreThreshold: hotThreshold,
    primaryHeadline: acc.headlines[0] || '',
    primaryUrl: acc.evidenceUrls[0] || '',
    combinedContext: acc.contextNotes.join(' | ')
  };
}).sort((a, b) => b.intentScore - a.intentScore);

const uniqueDomains = [...new Set(scoredAccounts.map((a) => a.domain).filter(Boolean))];

return [{
  json: {
    hasDomains: uniqueDomains.length > 0,
    accountCount: scoredAccounts.length,
    domains: uniqueDomains,
    accounts: scoredAccounts
  }
}];

const cfg = $('Configure ICP & Scoring Rules').first().json;
const scoredPayload = $('Normalize, Score & Deduplicate Accounts').first().json;
const accounts = Array.isArray(scoredPayload.accounts) ? scoredPayload.accounts : [];

const enrichedByDomain = new Map();
for (const item of $input.all()) {
  const d = String(item.json?.domain || item.json?.inputDomain || '').trim().toLowerCase();
  if (d) enrichedByDomain.set(d, item.json);
}

return accounts.map((acc) => {
  const enr = acc.domain ? (enrichedByDomain.get(acc.domain) || {}) : {};
  const bestEmail = String(enr.bestEmail || '').trim();
  const needsFallback = Boolean(enr.needsBrowserFallback);
  const techStack = Array.isArray(enr.techStackNames) ? enr.techStackNames.slice(0, 8).join(', ') : '';

  let routingTier = 'warm_archive';
  if (acc.intentScore >= acc.hotScoreThreshold && bestEmail) {
    routingTier = 'hot_ai_draft';
  } else if (needsFallback || (!bestEmail && acc.intentScore >= acc.hotScoreThreshold)) {
    routingTier = 'manual_claygent_queue';
  }

  return {
    json: {
      latestDate: acc.latestDate || '',
      company: acc.company,
      domain: acc.domain || '',
      intentScore: acc.intentScore,
      routingTier,
      sources: acc.sources.join(', '),
      triggers: acc.triggers.join(', '),
      primaryHeadline: acc.primaryHeadline,
      primaryUrl: acc.primaryUrl,
      combinedContext: acc.combinedContext,
      bestEmail,
      bestEmailRole: enr.bestEmailRole || '',
      linkedinUrl: enr.linkedinUrl || '',
      emailProvider: enr.emailProvider || '',
      dmarcPolicy: enr.dmarcPolicy || '',
      techStack,
      impressumDirector: enr.impressumManagingDirector || '',
      companySummary: enr.companySummary || '',
      needsBrowserFallback: needsFallback,
      enrichmentStatus: enr.enrichmentStatus || 'no_domain',
      senderName: cfg.senderName || 'Alex',
      offerSummary: cfg.offerSummary || ''
    }
  };
});

