const leads = $('Route by Lead Tier & Email Readiness').all(0);
const aiOutputs = $input.all();

return aiOutputs.map((aiItem, idx) => {
  const lead = (leads[idx] && leads[idx].json) ? leads[idx].json : {};
  const raw = String(aiItem.json?.message?.content || aiItem.json?.text || '').trim();
  let subject = `Quick note re: ${lead.company || 'your team'}`;
  let body = `Hi team,\n\nSaw the recent update on ${lead.primaryHeadline || lead.company}. Given your current momentum, thought our ${lead.offerSummary || 'outbound workflow'} could save your team hours each week.\n\nWorth a quick look?\n${lead.senderName || 'Alex'}`;

  try {
    const cleaned = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
    const parsed = JSON.parse(cleaned);
    if (parsed.subject) subject = String(parsed.subject).trim();
    if (parsed.body) body = String(parsed.body).trim();
  } catch {
    // Deterministic fallback already populated
  }

  const slackMessage = [
    `*HOT B2B LEAD (${lead.intentScore}/100) — ${lead.company}* (${lead.domain})`,
    `Triggers: ${lead.triggers} | Sources: ${lead.sources}`,
    `Signal: ${lead.primaryHeadline}`,
    lead.primaryUrl ? `Source URL: ${lead.primaryUrl}` : null,
    `Contact: ${lead.bestEmail} (${lead.bestEmailRole || 'business'}) | Provider: ${lead.emailProvider || 'N/A'} | Tech: ${lead.techStack || 'N/A'}`,
    `Gmail Draft Created -> Subject: "${subject}"`
  ].filter(Boolean).join('\n');

  return {
    json: {
      ...lead,
      emailSubject: subject,
      emailBody: body,
      slackMessage
    }
  };
});
